var e=[{title:`Навіщо поєднувати обидва`,text:`Силові тренування покращують силу та функцію м’язів, а аеробна активність підтримує витривалість і здоров’я серця та легень. Рекомендації громадського здоров’я радять обидва. Виконання лише одного може лишити частини вашої форми позаду, особливо коли ваші щоденні цілі включають силу, здатність ходити та залишатися активним тривалий час.`},{title:`Ефект інтерференції`,text:`Дуже великі обсяги роботи на витривалість іноді можуть зменшувати приріст вибухової потужності чи деяких показників сили порівняно з самими силовими тренуваннями. Однак нещодавні огляди знаходять, що комбіноване тренування загалом покращує аеробні можливості та силу разом, і більшість любителів не втрачає від цього жодного реального росту м’язів.`},{title:`Оберіть практичний порядок`,text:`Якщо пріоритет: сила, виконуйте вимогливі підйоми, поки ви свіжі, а легке кардіо після них. Якщо головна ціль: кондиція, спершу виконуйте важливу роботу на витривалість. Розведення важких занять на кілька годин чи на різні дні може допомогти з втомою, особливо у просунутому тренуванні.`},{title:`Збалансуйте важкі та легкі дні`,text:`Наприклад, зробіть два силові дні на все тіло плюс дві-три швидкі прогулянки та необов’язкове заняття помірною їздою на велосипеді. Досвідченішому атлету може знадобитися ретельно розрахувати час важких пробіжок і силових занять для ніг. Якщо страждають ваша результативність і відновлення, перестаньте нагромаджувати інтервали на максимум поверх кожного тренування ніг.`},{title:`Як це працює в TrainUp`,text:`Ваша ціль у Профілі (загальна форма, сила чи кондиція) підказує, який вид роботи ставити першим, поки ви все одно тренуєте обидва. Кардіо автоматично не руйнує силовий прогрес. Стежте за повтореннями, які ви пропускаєте, і за середнім зусиллям в Історії. Коли ви перегенеровуєте план, він стає легшим, якщо 2 з ваших останніх 3 тренувань були дуже важкими (RPE 9 або більше) чи завершені менш ніж на 60%.`}];var i=[{label:`Зонтичний огляд 2026: одночасне силове тренування та тренування на витривалість`,url:`https://pubmed.ncbi.nlm.nih.gov/41762427/`},{label:`CDC: рекомендації щодо фізичної активності для дорослих`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:e,sources:i};export{s as default,e as sections,i as sources};